mapper.select:
SELECT id, broker_type, token_type, access_token,
       issued_at, expires_at, created_at, updated_at
FROM broker_token
WHERE broker_type = #{brokerType}
  AND token_type = #{tokenType}
LIMIT 1

mapper.insert:
INSERT INTO broker_token (
    broker_type, token_type, access_token, issued_at, expires_at
) VALUES (
    #{brokerType}, #{tokenType}, #{accessToken}, #{issuedAt}, #{expiresAt}
)
ON DUPLICATE KEY UPDATE
    access_token = VALUES(access_token),
    issued_at    = VALUES(issued_at),
    expires_at   = VALUES(expires_at)
